import net from 'node:net';
import { createHash } from 'node:crypto';
function frame(op: number, payload: any): any { return Buffer.concat([Buffer.from([0x80 | op, payload.length]), payload]); }
function main(): void {
  const server = net.createServer((socket: any) => {
    let buf: any = Buffer.alloc(0);
    let up = false;
    socket.on('data', (d: any) => {
      buf = Buffer.concat([buf, d]);
      if (!up) {
        const end = buf.indexOf('\r\n\r\n');
        if (end < 0) return;
        const head: any = /Sec-WebSocket-Key: (.*)/i.exec(buf.subarray(0, end).toString());
        const accept = createHash('sha1').update(String(head[1]).trim() + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
        socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + accept + '\r\n\r\n');
        buf = buf.subarray(end + 4);
        up = true;
      }
      while (buf.length >= 6) {
        const op: number = buf[0] & 15;
        const len: number = buf[1] & 127;
        if (buf.length < 6 + len) break;
        const payload: any = Buffer.alloc(len);
        for (let i = 0; i < len; i++) payload[i] = buf[6 + i] ^ buf[2 + (i & 3)];
        buf = buf.subarray(6 + len);
        if (op === 1 || op === 2) socket.write(frame(op, payload));
        else if (op === 8) {
          console.log('server close', payload.readUInt16BE(0), payload.subarray(2).toString());
          socket.write(frame(8, payload));
          socket.end();
        }
      }
    });
    socket.on('error', () => {});
  });
  server.listen(0, '127.0.0.1', () => {
    const port = (server.address() as any).port;
    const ws: any = new WebSocket('ws://127.0.0.1:' + port + '/chat');
    ws.binaryType = 'arraybuffer';
    ws.onopen = () => { console.log('open', ws.readyState, ws.protocol === ''); ws.send('hi'); ws.send(new Uint8Array([1, 2, 3])); };
    let received = 0;
    ws.onmessage = (e: any) => {
      received++;
      if (typeof e.data === 'string') console.log('message text', e.data);
      else console.log('message bytes', e.data.byteLength, Array.from(new Uint8Array(e.data)).join(','));
      if (received === 2) ws.close(1000, 'bye');
    };
    ws.onclose = (e: any) => {
      console.log('close', e.code, e.reason, e.wasClean, ws.readyState);
      server.close();
    };
  });
}
